 jsonb_build_array('درک تفاوت مفهومی بین مدیریت واکنشی (پسرو) و مدیریت پیشگیرانه (پیشرو)'),
 jsonb_build_array('تکیه صرف بر نرخ حادثه صفر به‌عنوان تنها معیار موفقیت HSE','نادیده گرفتن روند نزولی در مشارکت مشاهدات ایمنی'),
 'HSE Plan پروژه'),

('supervision_manager','HSE','هماهنگی HSE بین چند پیمانکار','L2',
